import subprocess
import time
import json
import platform

LOGFILE_PATH = "logfile.log"


def _extract_first_float(text):
    number = []
    started = False
    for char in text:
        if char.isdigit() or char == ".":
            number.append(char)
            started = True
        elif started:
            break
    if not number:
        return None
    try:
        return float("".join(number))
    except ValueError:
        return None


def _run_command(command):
    try:
        output = subprocess.check_output(command, stderr=subprocess.STDOUT)
        return output.decode(errors="ignore")
    except Exception:
        return None


def _parse_windows_cpu(output):
    for line in output.splitlines():
        if "loadpercentage" in line.lower():
            value = line.split("=", 1)[-1].strip()
            parsed = _extract_first_float(value)
            if parsed is not None:
                return max(0.0, min(100.0, parsed))
    return None


def _parse_unix_cpu(output):
    for line in output.splitlines():
        lower = line.lower()
        if "cpu" not in lower:
            continue

        parts = line.split(",")
        total = 0.0
        found_value = False

        for part in parts:
            value = _extract_first_float(part)
            if value is None:
                continue
            found_value = True
            part_lower = part.lower()
            if "idle" in part_lower or "%id" in part_lower or part_lower.strip().endswith("id") or " id" in part_lower:
                return max(0.0, min(100.0, 100.0 - value))
            total += value

        if found_value:
            return max(0.0, min(100.0, total))

    return None


def _get_cpu_usage():
    system = platform.system().lower()

    if system.startswith("win"):
        commands = [
            ["wmic", "cpu", "get", "loadpercentage", "/value"],
            [
                "powershell",
                "-NoProfile",
                "-Command",
                "(Get-Counter '\\Processor(_Total)\\% Processor Time').CounterSamples.CookedValue",
            ],
        ]
        for command in commands:
            output = _run_command(command)
            if not output:
                continue
            parsed = _parse_windows_cpu(output)
            if parsed is not None:
                return parsed
        return None

    commands = [
        ["top", "-bn1"],
        ["ps", "-A", "-o", "%cpu"],
    ]
    for command in commands:
        output = _run_command(command)
        if not output:
            continue
        parsed = _parse_unix_cpu(output)
        if parsed is not None:
            return parsed

    return None


def task_func(interval, duration):
    interval = float(interval)
    duration = float(duration)

    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")

    records = []
    start = time.monotonic()
    end_time = start + duration
    next_sample = start

    while next_sample <= end_time:
        now = time.monotonic()
        if now < next_sample:
            time.sleep(next_sample - now)

        cpu_usage = _get_cpu_usage()
        records.append(
            {
                "timestamp": time.time(),
                "cpu_usage": cpu_usage,
            }
        )
        next_sample += interval

    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as file:
            json.dump(records, file)
    except OSError:
        return None

    return LOGFILE_PATH
